7: import InvalidAccountCard from "@/components/InvalidAccountCard";
8: 
9: export default function Root() {
10:   const [accountId, setAccountId] = useState<string | null>(null);
11:   const [loadingAccount, setLoadingAccount] = useState<boolean>(true);
12: 
13:   const loadAccountId = useCallback(() => {
14:     setLoadingAccount(true);
15:     const storedAccountId = getAccountId();
16:     setAccountId(storedAccountId);
17:     setLoadingAccount(false);
18:   }, []);
19: 
20:   useEffect(() => {
21:     loadAccountId();
22:   }, [loadAccountId]);
23: 
24:   useEffect(() => {
25:     const updateAccountId = (newAccountId: string | null) => {
26:       if (newAccountId) {
27:         setAccountId((currentId) => {
28:           if (currentId !== newAccountId) {
29:             setLoadingAccount(false);
30:             return newAccountId;
31:           }
32:           return currentId;
33:         });
34:       }
35:     };
36: 
37:     const handleAccountIdChange = (event: Event) => {
38:       const customEvent = event as CustomEvent<{ accountId: string }>;
39:       const newAccountId = customEvent.detail?.accountId || getAccountId();
40:       updateAccountId(newAccountId);
41:     };
42: 
43:     const handleStorageChange = (e: StorageEvent) => {
44:       if (e.key === "accountId") {
45:         const newAccountId = e.newValue || getAccountId();
46:         updateAccountId(newAccountId);
47:       }
48:     };
49: 
50:     window.addEventListener("accountIdChanged", handleAccountIdChange);
51:     window.addEventListener("storage", handleStorageChange);
52: 
53:     return () => {
54:       window.removeEventListener("accountIdChanged", handleAccountIdChange);
55:       window.removeEventListener("storage", handleStorageChange);
56:     };
57:   }, []);
58: 
59:   const handleRefreshAccount = useCallback(() => {
60:     window.location.reload();
61:   }, []);
62: 
63:   if (loadingAccount) {
64:     return (
65:       <QueryProvider>
66:         <QueryProvider>
67:           <div className={styles.container}>
68:             <Loading text="Carregando..." size="medium" />
69:           </div>
70:         </QueryProvider>
71:       </QueryProvider>
72:     );
73:   }
74: 
75:   if (!accountId) {
76:     return (
77:       <QueryProvider>
78:         <InvalidAccountCard handleClick={handleRefreshAccount} />
79:       </QueryProvider>
80:     );
81:   }
82: 
83:   return (
84:     <QueryProvider>
85:       <div className={styles.container}>
86:         <Statement accountId={accountId} onRefreshAccount={handleRefreshAccount} />
87:       </div>
88:     </QueryProvider>
89:   );
90: }

