1: import { registerApplication, start } from "single-spa";
2: import {
3:   constructApplications,
4:   constructRoutes,
5:   constructLayoutEngine,
6: } from "single-spa-layout";
7: import microfrontendLayout from "./microfrontend-layout.html";
8: import { checkAuthAndRedirect } from "./utils/auth";
9: import { initializeRouteAttributeListeners } from "./utils/route-attribute";
10: 
11: /**
12:  * Root Config - Orquestrador principal dos microfrontends
13:  *
14:  * Responsabilidades:
15:  * - Verificar autenticação e redirecionar conforme necessário
16:  * - Construir rotas e aplicações a partir do layout
17:  * - Registrar e inicializar aplicações Single-SPA
18:  * - Configurar listeners para atualização de atributos de rota
19:  */
20: 
21: // Verifica autenticação e redireciona antes de inicializar
22: checkAuthAndRedirect();
23: 
24: // Constrói rotas a partir do layout HTML
25: const routes = constructRoutes(microfrontendLayout);
26: 
27: // Constrói aplicações Single-SPA a partir das rotas
28: const applications = constructApplications({
29:   routes,
30:   loadApp({ name }) {
31:     return import(/* webpackIgnore: true */ name);
32:   },
33: });
34: 
35: // Constrói o layout engine para gerenciar o layout
36: const layoutEngine = constructLayoutEngine({ routes, applications });
37: 
38: // Registra todas as aplicações
39: applications.forEach(registerApplication);
40: 
41: // Ativa o layout engine
42: layoutEngine.activate();
43: 
44: // Inicia o Single-SPA
45: start();
46: 
47: // Inicializa listeners para atualização automática de atributos de rota
48: initializeRouteAttributeListeners();

